html='<!doctype html>\n<html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>__TITULO__ · Portafolio Ignacio Pizarro</title>\n<style>\n*{box-sizing:border-box}body{margin:0;background:#f3f5f7;color:#163246;font:15px system-ui,-apple-system,Segoe UI,sans-serif}header{background:#142f43;color:white;display:flex;justify-content:space-between;padding:19px 32px;gap:20px}header strong{letter-spacing:.05em}header span{color:#b7ced8;font-size:13px}.wrap{max-width:1440px;margin:auto;padding:25px 32px}h1{font-size:29px;margin:9px 0}h2{font-size:17px;margin:0 0 18px}p{line-height:1.5}.eyebrow{text-transform:uppercase;font-size:11px;letter-spacing:.14em;color:#146e78;font-weight:750}.top{display:flex;justify-content:space-between;align-items:center;gap:20px}.pill{font-size:12px;background:#e5f0ef;color:#155a61;padding:8px 12px;border-radius:20px}.note{padding:10px 14px;background:#fff4db;border-left:3px solid #b97c17;font-size:12px;margin:14px 0 18px;line-height:1.6}.filters{display:flex;align-items:end;gap:14px;margin:18px 0}.filters label{font-size:12px;font-weight:650;display:flex;flex-direction:column;gap:6px;flex:1}select,button{font:inherit;color:inherit;border:1px solid #c4cdd4;border-radius:5px;padding:10px;background:white;cursor:pointer}button:hover{background:#e9f2f3}button:focus-visible,select:focus-visible{outline:3px solid #b97c17;outline-offset:2px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin-bottom:18px}.card,.panel{background:white;border:1px solid #e1e7eb;border-radius:8px;padding:20px}.card label{font-size:12px;color:#4e6170}.value{display:block;font-size:29px;font-weight:650;letter-spacing:-.04em;margin:9px 0 6px}.meta{font-size:11px;color:#556977}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.barrow{display:grid;grid-template-columns:150px 1fr 100px;gap:12px;align-items:center;margin:15px 0;font-size:12px}.bar{height:18px;background:#eef3f6;border-radius:3px;overflow:hidden}.bar i{display:block;height:100%;background:#18727b;border-radius:3px}.barrow:nth-child(2n) i{background:#416c9b}.barrow output{text-align:right}.panel p{font-size:12px;color:#5a6b76;margin:14px 0 0}.tablewrap{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:12px}th{text-align:left;border-bottom:2px solid #d7e1e7;padding:10px 9px;font-size:11px;color:#506876}td{padding:10px 9px;border-bottom:1px solid #e6ebee}td.num{text-align:right;font-variant-numeric:tabular-nums}.full{margin-top:18px}footer{font-size:11px;line-height:1.6;margin-top:18px;color:#556a78}.tabs{display:flex;gap:8px;margin:16px 0}button[aria-pressed=true]{background:#163c52;color:white;border-color:#163c52}.hide{display:none}.totals{font-size:12px;color:#516978}svg{width:100%;height:160px}svg text{font:11px system-ui;fill:#516978}.tablewrap td:first-child{white-space:nowrap}@media(max-width:850px){.wrap{padding:18px}.cards{grid-template-columns:1fr 1fr}.grid{grid-template-columns:1fr}.filters{flex-wrap:wrap}.filters label{min-width:180px}header{padding:16px}.top{align-items:start;flex-direction:column}.barrow{grid-template-columns:120px 1fr 80px}}@media print{button{display:none}.wrap{padding:12px}}\n</style>\n<header><strong>IP / ANALÍTICA DE GESTIÓN</strong><span>Ignacio Pizarro Hurtado · Portafolio profesional</span></header>\n<main class="wrap"><div class="top"><div><div class="eyebrow">__ETIQUETA__</div><h1 id="titulo"></h1><div id="subtitulo" class="meta"></div></div><span class="pill">100 % sintético · semilla 20261016</span></div>\n<div class="note"><strong>__AVISO__</strong> Visor web de verificación de cálculos y filtros. Power BI Desktop, M y DAX: validación nativa pendiente. Las cifras no son resultados de las organizaciones.</div>\n<div class="filters"><label>Proyecto<select id="caso">__OPCIONES__</select></label><label id="lblfecha">Período<select id="periodo"></select></label><label id="lblcat">Categoría<select id="categoria"></select></label><button id="restablecer">Restablecer</button></div>\n<div class="tabs"><button id="resumen" aria-pressed="true">Resumen de gestión</button><button id="operacion" aria-pressed="false">Detalle y conciliación</button></div>\n<section class="cards" id="kpis" aria-label="Indicadores del contexto" aria-live="polite"></section>\n<section class="grid" id="graficos"><div class="panel"><h2 id="t1"></h2><div id="graf1"></div><p id="pie1"></p></div><div class="panel"><h2 id="t2"></h2><div id="graf2"></div><p id="pie2"></p></div></section>\n<section class="panel full"><div class="top"><h2 id="tablaTitulo">Conciliación del contexto</h2><span id="nfilas" class="totals"></span></div><div class="tablewrap"><table id="tabla"></table></div><p id="pieTabla"></p></section>\n<footer><strong>Linaje verificable:</strong> __LINAJE__<br>Trabajo histórico de Ignacio con las colaboraciones documentadas. Esta recreación técnica de 2026 es posterior y recibió asistencia de IA. No es una captura histórica ni una captura de Power BI Desktop. Sin afiliación o endoso institucional.</footer></main>\n<script>const datos=__DATOS__;\n__MODELO__\nconst $=s=>document.getElementById(s),num=(v,t=\'n\')=>v===null||v===undefined?\'Sin base\':new Intl.NumberFormat(\'es-CL\',t===\'clp\'?{style:\'currency\',currency:\'CLP\',maximumFractionDigits:0}:t===\'pct\'?{style:\'percent\',maximumFractionDigits:1}:{maximumFractionDigits:1}).format(v);\nconst esc=x=>String(x??\'—\').replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c]));\nlet detalle=false;\nfunction opts(el,arr,all=true){el.innerHTML=(all?\'<option value="">Todos</option>\':\'\')+arr.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join(\'\');}\nfunction grupos(rows,key,value=null){const out={};for(const r of rows){const k=r[key]??\'Sin categoría\';out[k]=(out[k]||0)+(value?Number(r[value]||0):1);}return Object.entries(out).sort((a,b)=>a[0].localeCompare(b[0]));}\nfunction bars(el,values,type=\'n\'){const max=Math.max(...values.map(x=>Math.abs(x[1])),1);el.innerHTML=values.length?values.map(([k,v])=>`<div class="barrow"><span>${esc(k)}</span><div class="bar"><i style="width:${Math.abs(v)/max*100}%"></i></div><output>${num(v,type)}</output></div>`).join(\'\'):\'<p>Sin observaciones en este contexto.</p>\';}\nfunction tabla(headers,rows){$(\'tabla\').innerHTML=\'<thead><tr>\'+headers.map(x=>\'<th>\'+esc(x)+\'</th>\').join(\'\')+\'</tr></thead><tbody>\'+rows.map(r=>\'<tr>\'+r.map((v,i)=>`<td class="${i?\'num\':\'\'}">${esc(v)}</td>`).join(\'\')+\'</tr>\').join(\'\')+\'</tbody>\';}\nfunction setup(){const c=$(\'caso\').value;let fechas=[],cats=[];\n if(c===\'A\'||c===\'B\'){const p=datos.proyectos[c];fechas=[...new Set(p.calendario.map(x=>x.Fecha.slice(0,7)))];cats=c===\'A\'?[\'Tenis\',\'Pádel\']:[...new Set(p.registros.filter(x=>x[\'LINEA DE NEGOCIO\']!==\'TIENDA\'&&![\'PAGO G3\',\'COPA LITORAL\'].includes(x[\'SUBLINEA DE NEGOCIO\'])).map(x=>x[\'LINEA DE NEGOCIO\'].replace(\'ESCALERILLA\',\'ESCALERILLA TENIS\')))].sort();}\n else if(c===\'F\'){fechas=[...new Set(datos.FactSeguimiento.map(x=>x.corte))].sort();cats=datos.cursos.map(x=>x.curso_id);}\n else{fechas=datos.calendario.map(x=>x.fecha);cats=datos.programas.map(x=>x.programa_id);}\n opts($(\'periodo\'),fechas,c!==\'F\');if(c===\'F\')$(\'periodo\').value=fechas.at(-1);opts($(\'categoria\'),cats);render();}\nfunction render(){const c=$(\'caso\').value,mes=$(\'periodo\').value,cat=$(\'categoria\').value;const r=calcular(datos,c,mes,cat);\n const names={A:\'GHTOP / uso de canchas\',B:\'GHTOP / movimientos y líneas\',F:\'Formación / seguimiento al corte\',E:\'Educación Inicial / cobertura y asistencia\'};\n $(\'titulo\').textContent=names[c];$(\'subtitulo\').textContent=(c===\'A\'?\'03 nov 2025 — 23 ene 2026 · noviembre y enero parciales\':c===\'B\'?\'17 mar — 19 jun 2026 · marzo y junio parciales\':c===\'F\'?\'Snapshot de inscripción–corte · personas distintas por contexto\':\'Universo esperado participante–día · cierre inventado 10 de junio\');\n $(\'kpis\').innerHTML=r.metricas.map(([label,v,t,base])=>`<article class="card"><label>${esc(label)}</label><output class="value">${num(v,t)}</output><div class="meta">${esc(base)}</div></article>`).join(\'\');\n const meses=(c===\'A\'||c===\'B\')?[...new Set(datos.proyectos[c].calendario.map(x=>x.Fecha.slice(0,7)))]:c===\'F\'?[...new Set(datos.FactSeguimiento.map(x=>x.corte))].sort():datos.calendario.map(x=>x.fecha);\n $(\'t1\').textContent=(c===\'A\'||c===\'B\')?\'Monto registrado por período · CLP\':\'Estados en el contexto seleccionado\';\n $(\'t2\').textContent=c===\'A\'?\'Horas por deporte\':c===\'B\'?\'Monto positivo por línea · CLP\':c===\'F\'?\'Personas por corte · no aditivas\':\'Cobertura por programa\';\n if(c===\'A\'||c===\'B\'){\n  bars($(\'graf1\'),meses.filter(x=>!mes||x===mes).map(m=>[m,calcular(datos,c,m,cat).k.monto_registrado]),\'clp\');\n  if(c===\'A\')bars($(\'graf2\'),[\'Tenis\',\'Pádel\'].filter(x=>!cat||cat===x).map(x=>[x,calcular(datos,c,mes,x).k.horas]));\n  else bars($(\'graf2\'),grupos(r.rows.filter(x=>x[r.monto]>0),r.categoria,r.monto),\'clp\');\n  $(\'pie1\').textContent=\'Los meses extremos son parciales; el total mensual no demuestra mejora ni efecto causal.\';$(\'pie2\').textContent=c===\'A\'?\'Capacidad: días abiertos del calendario × 14 h × canchas del deporte. No usa solo días con reservas.\':\'Se excluyen TIENDA, PAGO G3 y COPA LITORAL por contrato del universo. Los negativos no entran en monto positivo.\';\n  const keys=[...new Set(r.rows.map(x=>x[r.categoria]))].sort();tabla([\'Deporte / línea\',\'Filas\',\'Monto con signo\',\'Monto positivo\',c===\'A\'?\'Horas\':\'Promedio positivo\'],keys.map(x=>{const k=calcular(datos,c,mes,x).k;return[x,num(k.filas),num(k.monto_registrado,\'clp\'),num(k.monto_positivo,\'clp\'),num(c===\'A\'?k.horas:k.ticket_positivo,c===\'A\'?\'n\':\'clp\')];}));\n }else{\n  bars($(\'graf1\'),grupos(r.rows,\'estado\'));\n  if(c===\'F\')bars($(\'graf2\'),meses.map(m=>[m,calcular(datos,c,m,cat).k.personas]));else bars($(\'graf2\'),datos.programas.filter(p=>!cat||p.programa_id===cat).map(p=>[p.programa_id,calcular(datos,c,mes,p.programa_id).k.cobertura]),\'pct\');\n  $(\'pie1\').textContent=c===\'F\'?\'La aprobación usa solo inscripciones de cursos cerrados al corte. Sin base se muestra Sin base.\':\'Presente, Ausente y Sin registro son estados distintos; no se imputan faltantes.\';$(\'pie2\').textContent=c===\'F\'?\'Cambiar un estado futuro no altera un corte pasado. El total de personas se recalcula, no suma cursos.\':\'Primero se construye el universo esperado con matrícula vigente y calendario; luego se unen observaciones.\';\n  if(c===\'F\')tabla([\'Curso\',\'Inscripciones\',\'Personas\',\'Aprobadas / cerradas\',\'Aprobación\'],datos.cursos.filter(x=>!cat||x.curso_id===cat).map(x=>{const k=calcular(datos,c,mes,x.curso_id).k;return[x.curso_id,k.inscripciones,k.personas,`${k.aprobadas_curso_cerrado} / ${k.inscripciones_curso_cerrado}`,num(k.aprobacion_curso_cerrado,\'pct\')];}));\n  else tabla([\'Programa\',\'Esperadas\',\'Recibidas\',\'Sin registro\',\'Asistencia observada\'],datos.programas.filter(x=>!cat||x.programa_id===cat).map(x=>{const k=calcular(datos,c,mes,x.programa_id).k;return[x.programa_id,k.jornadas_esperadas,k.registros_recibidos,k.sin_registro,num(k.asistencia_observada,\'pct\')];}));\n }\n $(\'nfilas\').textContent=`${num(r.rows.length)} filas filtradas · contexto ${mes||\'todos los períodos\'}`;$(\'pieTabla\').textContent=\'Totales recalculados sobre el contexto. Datos 100 % inventados; consulte los contratos, DAX/M y pruebas del repositorio.\';\n if(detalle){const cols=Object.keys(r.rows[0]||{});tabla(cols,r.rows.slice(0,18).map(x=>cols.map(k=>x[k])));$(\'tablaTitulo\').textContent=\'Detalle de filas · primeras 18 del contexto\';$(\'pieTabla\').textContent=\'Vista de inspección: no representa el total completo. Descargue los CSV para conciliación.\';}else $(\'tablaTitulo\').textContent=\'Conciliación del contexto\';\n $(\'graficos\').classList.toggle(\'hide\',detalle);$(\'resumen\').setAttribute(\'aria-pressed\',!detalle);$(\'operacion\').setAttribute(\'aria-pressed\',detalle);\n}\n$(\'caso\').addEventListener(\'change\',setup);$(\'periodo\').addEventListener(\'change\',render);$(\'categoria\').addEventListener(\'change\',render);$(\'restablecer\').addEventListener(\'click\',setup);$(\'resumen\').addEventListener(\'click\',()=>{detalle=false;render()});$(\'operacion\').addEventListener(\'click\',()=>{detalle=true;render()});setup();\n</script></html>'
